// Type declarations for side-effect imports from @formatjs/intl-pluralrules.
// The package has .d.ts files but TypeScript's module resolution for hoisted
// monorepo packages with .js export maps doesn't always resolve them.
declare module '@formatjs/intl-pluralrules/polyfill';
declare module '@formatjs/intl-pluralrules/polyfill-force';
declare module '@formatjs/intl-pluralrules/locale-data/*';
